    "\u8f93\u51fa long \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def countMajoritySubarrays(self, nums: List[int], target: int) -> int:\n        n = len(nums)\n        # \u8868\u793a\u524d\u7f00\u548c\u4e3a -n, -(n-1), ..., 0, 1, ..., n \u7684\u524d\u7f00\u6570\u91cf\uff0c\u4e0b\u6807\u504f\u79fb n\n        pre = [0] * (n * 2 + 1)\n        pre[n] = 1\n        cnt = n\n        ans = presum = 0\n        for i in range(n):\n            if nums[i] == target:\n                presum += pre[cnt]\n                cnt += 1\n                pre[cnt] += 1\n            else:\n                cnt -= 1\n                presum -= pre[cnt]\n                pre[cnt] += 1\n            ans += presum\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.countMajoritySubarrays(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "exact",
    [["[1,2,2,3]\n2", "5"], ["[1,1,1,1]\n1", "10"], ["[1,2,3]\n4", "0"]],
