    "\u8f93\u51fa list<integer> \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def minimumFlips(self, n: int, edges: List[List[int]], start: str, target: str) -> List[int]:\n        '''\n        \u6811\u5f62dp\n        '''                \n        road = defaultdict(list)\n        for i,(x,y) in enumerate(edges):\n            road[x].append((y,i))\n            road[y].append((x,i))\n        \n        res = []\n        # \u8fd4\u56de\u5f53\u524d\u8282\u70b9\u7b26\u5408\u9898\u610f\u7684\u6700\u5c11\u64cd\u4f5c\u6570\uff0c\u4ee5\u53ca\u662f\u5426\u6b20\u4e00\u6b21\u53cd\u8f6c        \n        def dfs(node,last):   \n            # t \u6700\u5c11\u64cd\u4f5c\u6570  \n            # f \u5f53\u524d\u8282\u70b9\u662f\u5426\u9700\u8981\u53cd\u8f6c  \n            if start[node] == target[node]:\n                f = 0\n            else:\n                f = 1      \n            t = 0\n            for nxt,i in road[node]:              \n                if last == nxt:\n                    continue\n                \n                lt,lf = dfs(nxt,node)\n                t += lt\n                # \u9700\u8981\u53cd\u8f6c\u5f53\u524d\u8fb9\n                if lf:\n                    t += 1\n                    f = 1 - f\n                    res.append(i)                        \n            return t,f\n        \n        t,f = dfs(0,-1)\n        if f:                   \n            return [-1]       \n        \n        return sorted(res)\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.minimumFlips(_args[0], _args[1], _args[2], _args[3])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
