    "hard",
    "\u6811",
    "\u7ed9\u4f60\u4e00\u4e2a\u6570\u7ec4\u00a0pairs \uff0c\u5176\u4e2d\u00a0pairs[i] = [xi, yi]\u00a0\uff0c\u5e76\u4e14\u6ee1\u8db3\uff1a\n\n\tpairs\u00a0\u4e2d\u6ca1\u6709\u91cd\u590d\u5143\u7d20\n\n\txi i\n\n\u4ee4\u00a0ways\u00a0\u4e3a\u6ee1\u8db3\u4e0b\u9762\u6761\u4ef6\u7684\u6709\u6839\u6811\u7684\u65b9\u6848\u6570\uff1a\n\n\t\u6811\u6240\u5305\u542b\u7684\u6240\u6709\u8282\u70b9\u503c\u90fd\u5728 pairs\u00a0\u4e2d\u3002\n\n\t\u4e00\u4e2a\u6570\u5bf9\u00a0[xi, yi] \u51fa\u73b0\u5728\u00a0pairs\u00a0\u4e2d\u00a0\u5f53\u4e14\u4ec5\u5f53\u00a0xi\u00a0\u662f\u00a0yi\u00a0\u7684\u7956\u5148\u6216\u8005\u00a0yi\u00a0\u662f\u00a0xi\u00a0\u7684\u7956\u5148\u3002\n\n\t\u6ce8\u610f\uff1a\u6784\u9020\u51fa\u6765\u7684\u6811\u4e0d\u4e00\u5b9a\u662f\u4e8c\u53c9\u6811\u3002\n\n\u4e24\u68f5\u6811\u88ab\u89c6\u4e3a\u4e0d\u540c\u7684\u65b9\u6848\u5f53\u5b58\u5728\u81f3\u5c11\u4e00\u4e2a\u8282\u70b9\u5728\u4e24\u68f5\u6811\u4e2d\u6709\u4e0d\u540c\u7684\u7236\u8282\u70b9\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\uff1a\n\n\t\u5982\u679c\u00a0ways == 0\u00a0\uff0c\u8fd4\u56de\u00a00\u00a0\u3002\n\n\t\u5982\u679c\u00a0ways == 1\u00a0\uff0c\u8fd4\u56de 1\u00a0\u3002\n\n\t\u5982\u679c\u00a0ways > 1\u00a0\uff0c\u8fd4\u56de\u00a02\u00a0\u3002\n\n\u4e00\u68f5 \u6709\u6839\u6811\u00a0\u6307\u7684\u662f\u53ea\u6709\u4e00\u4e2a\u6839\u8282\u70b9\u7684\u6811\uff0c\u6240\u6709\u8fb9\u90fd\u662f\u4ece\u6839\u5f80\u5916\u7684\u65b9\u5411\u3002\n\n\u6211\u4eec\u79f0\u4ece\u6839\u5230\u4e00\u4e2a\u8282\u70b9\u8def\u5f84\u4e0a\u7684\u4efb\u610f\u4e00\u4e2a\u8282\u70b9\uff08\u9664\u53bb\u8282\u70b9\u672c\u8eab\uff09\u90fd\u662f\u8be5\u8282\u70b9\u7684 \u7956\u5148\u00a0\u3002\u6839\u8282\u70b9\u6ca1\u6709\u7956\u5148\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1apairs = [[1,2],[2,3]]\n\u8f93\u51fa\uff1a1\n\u89e3\u91ca\uff1a\u5982\u4e0a\u56fe\u6240\u793a\uff0c\u6709\u4e14\u53ea\u6709\u4e00\u4e2a\u7b26\u5408\u89c4\u5b9a\u7684\u6709\u6839\u6811\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1apairs = [[1,2],[2,3],[1,3]]\n\u8f93\u51fa\uff1a2\n\u89e3\u91ca\uff1a\u6709\u591a\u4e2a\u7b26\u5408\u89c4\u5b9a\u7684\u6709\u6839\u6811\uff0c\u5176\u4e2d\u4e09\u4e2a\u5982\u4e0a\u56fe\u6240\u793a\u3002\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1apairs = [[1,2],[2,3],[2,4],[1,5]]\n\u8f93\u51fa\uff1a0\n\u89e3\u91ca\uff1a\u6ca1\u6709\u7b26\u5408\u89c4\u5b9a\u7684\u6709\u6839\u6811\u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 5\n\n\t1 i i\n\n\tpairs\u00a0\u4e2d\u7684\u5143\u7d20\u4e92\u4e0d\u76f8\u540c\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1apairs\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def checkWays(self, pairs: List[List[int]]) -> int:\n        adj = defaultdict(set)\n        for x, y in pairs:\n            adj[x].add(y)\n            adj[y].add(x)\n\n        # \u68c0\u6d4b\u662f\u5426\u5b58\u5728\u6839\u8282\u70b9\n        root = next((node for node, neighbours in adj.items() if len(neighbours) == len(adj) - 1), -1)\n        if root == -1:\n            return 0\n\n        ans = 1\n        for node, neighbours in adj.items():\n            if node == root:\n                continue\n\n            currDegree = len(neighbours)\n            parent = -1\n            parentDegree = maxsize\n            # \u6839\u636e degree \u7684\u5927\u5c0f\u627e\u5230 node \u7684\u7236\u8282\u70b9 parent\n            for neighbour in neighbours:\n                if currDegree <= len(adj[neighbour]) < parentDegree:\n                    parent = neighbour\n                    parentDegree = len(adj[neighbour])\n            # \u68c0\u6d4b neighbours \u662f\u5426\u4e3a adj[parent] \u7684\u5b50\u96c6\n            if parent == -1 or any(neighbour != parent and neighbour not in adj[parent] for neighbour in neighbours):\n                return 0\n\n            if parentDegree == currDegree:\n                ans = 2\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.checkWays(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
