    "LeetCode 2509",
    "hard",
    "\u6811",
    "\u7ed9\u4f60\u4e00\u4e2a\u6574\u6570\u00a0n\u00a0\uff0c\u8868\u793a\u4f60\u6709\u4e00\u68f5\u542b\u6709\u00a02n - 1\u00a0\u4e2a\u8282\u70b9\u7684 \u5b8c\u5168\u4e8c\u53c9\u6811\u00a0\u3002\u6839\u8282\u70b9\u7684\u7f16\u53f7\u662f\u00a01\u00a0\uff0c\u6811\u4e2d\u7f16\u53f7\u5728[1, 2n - 1 - 1]\u00a0\u4e4b\u95f4\uff0c\u7f16\u53f7\u4e3a\u00a0val\u00a0\u7684\u8282\u70b9\u90fd\u6709\u4e24\u4e2a\u5b50\u8282\u70b9\uff0c\u6ee1\u8db3\uff1a\n\n\t\u5de6\u5b50\u8282\u70b9\u7684\u7f16\u53f7\u4e3a\u00a02 * val\n\n\t\u53f3\u5b50\u8282\u70b9\u7684\u7f16\u53f7\u4e3a\u00a02 * val + 1\n\n\u7ed9\u4f60\u4e00\u4e2a\u957f\u5ea6\u4e3a m\u00a0\u7684\u67e5\u8be2\u6570\u7ec4 queries\u00a0\uff0c\u5b83\u662f\u4e00\u4e2a\u4e8c\u7ef4\u6574\u6570\u6570\u7ec4\uff0c\u5176\u4e2d\u00a0queries[i] = [ai, bi]\u00a0\u3002\u5bf9\u4e8e\u6bcf\u4e2a\u67e5\u8be2\uff0c\u6c42\u51fa\u4ee5\u4e0b\u95ee\u9898\u7684\u89e3\uff1a\n\n\t\u5728\u8282\u70b9\u7f16\u53f7\u4e3a\u00a0ai \u548c\u00a0bi\u00a0\u4e4b\u95f4\u6dfb\u52a0\u4e00\u6761\u8fb9\u3002\n\n\t\u6c42\u51fa\u56fe\u4e2d\u73af\u7684\u957f\u5ea6\u3002\n\n\t\u5220\u9664\u8282\u70b9\u7f16\u53f7\u4e3a\u00a0ai \u548c\u00a0bi\u00a0\u4e4b\u95f4\u65b0\u6dfb\u52a0\u7684\u8fb9\u3002\n\n\u6ce8\u610f\uff1a\n\n\t\u73af \u662f\u5f00\u59cb\u548c\u7ed3\u675f\u4e8e\u540c\u4e00\u8282\u70b9\u7684\u4e00\u6761\u8def\u5f84\uff0c\u8def\u5f84\u4e2d\u6bcf\u6761\u8fb9\u90fd\u53ea\u4f1a\u88ab\u8bbf\u95ee\u4e00\u6b21\u3002\n\n\t\u73af\u7684\u957f\u5ea6\u662f\u73af\u4e2d\u8fb9\u7684\u6570\u76ee\u3002\n\n\t\u5728\u6811\u4e2d\u6dfb\u52a0\u989d\u5916\u7684\u8fb9\u540e\uff0c\u4e24\u4e2a\u70b9\u4e4b\u95f4\u53ef\u80fd\u4f1a\u6709\u591a\u6761\u8fb9\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u4e00\u4e2a\u957f\u5ea6\u4e3a m\u00a0\u7684\u6570\u7ec4\u00a0answer\u00a0\uff0c\u5176\u4e2d\u00a0answer[i]\u00a0\u662f\u7b2c\u00a0i\u00a0\u4e2a\u67e5\u8be2\u7684\u7ed3\u679c\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1an = 3, queries = [[5,3],[4,7],[2,3]]\n\u8f93\u51fa\uff1a[4,5,3]\n\u89e3\u91ca\uff1a\u4e0a\u56fe\u662f\u4e00\u68f5\u6709 23 - 1 \u4e2a\u8282\u70b9\u7684\u6811\u3002\u7ea2\u8272\u8282\u70b9\u8868\u793a\u6dfb\u52a0\u989d\u5916\u8fb9\u540e\u5f62\u6210\u73af\u7684\u8282\u70b9\u3002\n- \u5728\u8282\u70b9 3 \u548c\u8282\u70b9 5 \u4e4b\u95f4\u6dfb\u52a0\u8fb9\u540e\uff0c\u73af\u4e3a [5,2,1,3] \uff0c\u6240\u4ee5\u7b2c\u4e00\u4e2a\u67e5\u8be2\u7684\u7ed3\u679c\u662f 4 \u3002\u5220\u6389\u6dfb\u52a0\u7684\u8fb9\u540e\u5904\u7406\u4e0b\u4e00\u4e2a\u67e5\u8be2\u3002\n- \u5728\u8282\u70b9 4 \u548c\u8282\u70b9 7 \u4e4b\u95f4\u6dfb\u52a0\u8fb9\u540e\uff0c\u73af\u4e3a [4,2,1,3,7] \uff0c\u6240\u4ee5\u7b2c\u4e8c\u4e2a\u67e5\u8be2\u7684\u7ed3\u679c\u662f 5 \u3002\u5220\u6389\u6dfb\u52a0\u7684\u8fb9\u540e\u5904\u7406\u4e0b\u4e00\u4e2a\u67e5\u8be2\u3002\n- \u5728\u8282\u70b9 2 \u548c\u8282\u70b9 3 \u4e4b\u95f4\u6dfb\u52a0\u8fb9\u540e\uff0c\u73af\u4e3a [2,1,3] \uff0c\u6240\u4ee5\u7b2c\u4e09\u4e2a\u67e5\u8be2\u7684\u7ed3\u679c\u662f 3 \u3002\u5220\u6389\u6dfb\u52a0\u7684\u8fb9\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1an = 2, queries = [[1,2]]\n\u8f93\u51fa\uff1a[2]\n\u89e3\u91ca\uff1a\u4e0a\u56fe\u662f\u4e00\u68f5\u6709 22 - 1 \u4e2a\u8282\u70b9\u7684\u6811\u3002\u7ea2\u8272\u8282\u70b9\u8868\u793a\u6dfb\u52a0\u989d\u5916\u8fb9\u540e\u5f62\u6210\u73af\u7684\u8282\u70b9\u3002\n- \u5728\u8282\u70b9 1 \u548c\u8282\u70b9 2 \u4e4b\u95f4\u6dfb\u52a0\u8fb9\u540e\uff0c\u73af\u4e3a [2,1] \uff0c\u6240\u4ee5\u7b2c\u4e00\u4e2a\u67e5\u8be2\u7684\u7ed3\u679c\u662f 2 \u3002\u5220\u6389\u6dfb\u52a0\u7684\u8fb9\u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t2 <= n <= 30\n\n\tm == queries.length\n\n\t1 <= m <= 105\n\n\tqueries[i].length == 2\n\n\t1 <= ai, bi <= 2n - 1\n\n\tai != bi",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1an\u3001queries\u3002",
    "\u8f93\u51fa integer[] \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\ndef calc(t):\r\n    sa, sb = map(lambda x: [x >> i for i in range(x.bit_length())], t)\r\n    while sa and sb and sa[-1] == sb[-1]: sa.pop(); sb.pop()\r\n    return len(sa) + len(sb) + 1\r\nclass Solution:\r\n    def cycleLengthQueries(self, n: int, queries: List[List[int]]) -> List[int]:\r\n        return list(map(calc, queries))\r\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.cycleLengthQueries(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "int_list",
    [["3\n[[5,3],[4,7],[2,3]]", "[4,5,3]"], ["2\n[[1,2]]", "[2]"]],
    ["tree", "array", "binary-tree", "lowest-common-ancestor", "binary-lifting", "\u6811"],
