    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution(object):\n    def countOfPeaks(self, nums, queries):\n        \"\"\"\n        :type nums: List[int]\n        :type queries: List[List[int]]\n        :rtype: List[int]\n        \"\"\"\n        \n        n = len(nums)\n        peak = [False] * n\n\n        for index in range(1, n - 1):\n            peak[index] = (nums[index] > nums[index - 1] and nums[index] > nums[index + 1])\n\n        f = [0] * (n * 4)\n        first = [None] * (n * 4)\n        last = [None] * (n * 4)\n\n        def build(p, left, right):\n            if left == right:\n                if peak[left]:\n                    first[p] = left\n                    last[p] = left\n                return\n\n            mid = (left + right) // 2\n            build(p * 2 + 1, left, mid)\n            build(p * 2 + 2, mid + 1, right)\n            \n            f[p] = f[p * 2 + 1] + f[p * 2 + 2]\n            if last[p * 2 + 1] is not None and first[p * 2 + 2] is not None:\n                f[p] += last[p * 2 + 1] * (first[p * 2 + 2] - last[p * 2 + 1])\n            \n            if first[p * 2 + 1] is None:\n                first[p] = first[p * 2 + 2]\n            else:\n                first[p] = first[p * 2 + 1]\n            \n            if last[p * 2 + 2] is None:\n                last[p] = last[p * 2 + 1]\n            else:\n                last[p] = last[p * 2 + 2]\n        \n        def query(p, left, right, start, end):\n            if start == left and right == end:\n                return f[p], first[p], last[p]\n            \n            mid = (left + right) // 2\n            if end <= mid:\n                return query(p * 2 + 1, left, mid, start, end)\n            elif start > mid:\n                return query(p * 2 + 2, mid + 1, right, start, end)\n            else:\n                left_v, left_first, left_last = query(p * 2 + 1, left, mid, start, mid)\n                right_v, right_first, right_last = query(p * 2 + 2, mid + 1, right, mid + 1, end)\n\n                tot = left_v + right_v\n                if left_last is not None and right_first is not None:\n                    tot += left_last * (right_first - left_last)\n\n                if left_first is None:\n                    interval_first = right_first\n                else:\n                    interval_first = left_first\n\n                if right_last is None:\n                    interval_last = left_last\n                else:\n                    interval_last = right_last\n\n                return tot, interval_first, interval_last\n        \n        def update(p, left, right, index):\n            if left == right:\n                if peak[index]:\n                    first[p] = index\n                    last[p] = index\n                else:\n                    first[p] = None\n                    last[p] = None\n                return    \n            \n            mid = (left + right) // 2\n            if index <= mid:\n                update(p * 2 + 1, left, mid, index)\n            else:\n                update(p * 2 + 2, mid + 1, right, index)\n            \n            f[p] = f[p * 2 + 1] + f[p * 2 + 2]\n            if last[p * 2 + 1] is not None and first[p * 2 + 2] is not None:\n                f[p] += last[p * 2 + 1] * (first[p * 2 + 2] - last[p * 2 + 1])\n            \n            if first[p * 2 + 1] is None:\n                first[p] = first[p * 2 + 2]\n            else:\n                first[p] = first[p * 2 + 1]\n            \n            if last[p * 2 + 2] is None:\n                last[p] = last[p * 2 + 1]\n            else:\n                last[p] = last[p * 2 + 2]\n        \n        build(0, 0, n - 1)\n\n        res = []\n        for q in queries:\n            if q[0] == 1:\n                tot, interval_first, interval_last = query(0, 0, n - 1, q[1], q[2])\n                if interval_first is None:\n                    res.append(0)\n                elif interval_first == interval_last:\n                    res.append((interval_first - q[1]) * (q[2] - interval_first))\n                else:\n                    res.append(tot + interval_last * (q[2] - interval_last) - q[1] * (q[2] - interval_first))\n            \n            else:\n                pending = []\n                nums[q[1]] = q[2]\n                for index in range(q[1] - 1, q[1] + 2):\n                    if index <= 0 or index >= n - 1:\n                        continue\n                    \n                    ori = peak[index]\n                    peak[index] = (nums[index] > nums[index - 1] and nums[index] > nums[index + 1])\n                    if ori and not peak[index]:\n                        update(0, 0, n - 1, index)\n                    elif not ori and peak[index]:\n                        pending.append(index)\n                \n                for index in pending:\n                    update(0, 0, n - 1, index)\n                \n                nums[q[1]] = q[2]\n\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.countOfPeaks(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
