    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:\n        bMin1 = [2**31 - 1] * (n + 1)\n        bMin2 = [2**31 - 1] * (n + 1)\n        for pair in conflictingPairs:\n            a = min(pair[0], pair[1])\n            b = max(pair[0], pair[1])\n            if bMin1[a] > b:\n                bMin2[a] = bMin1[a]\n                bMin1[a] = b\n            elif bMin2[a] > b:\n                bMin2[a] = b\n        res = 0\n        ib1 = n\n        b2 = 0x3FFFFFFF\n        delCount = [0] * (n + 1)\n        for i in range(n, 0, -1):\n            if bMin1[ib1] > bMin1[i]:\n                b2 = min(b2, bMin1[ib1])\n                ib1 = i\n            else:\n                b2 = min(b2, bMin1[i])\n            res += min(bMin1[ib1], n + 1) - i\n            delCount[ib1] += min(min(b2, bMin2[ib1]), n + 1) - min(bMin1[ib1], n + 1)\n        return res + max(delCount)\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maxSubarrays(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
