PTH11 = mk(
    "TH11",
    "\u77e9\u5f62\u9762\u79ef II",
    "LeetCode 850",
    "hard",
    "\u6811",
    "\u7ed9\u4f60\u4e00\u4e2a\u8f74\u5bf9\u9f50\u7684\u4e8c\u7ef4\u6570\u7ec4\u00a0rectangles\u00a0\u3002 \u5bf9\u4e8e\u00a0rectangle[i] = [x1, y1, x2, y2]\uff0c\u5176\u4e2d\u00a0(xi1, yi1)\u00a0\u662f\u8be5\u77e9\u5f62 \u5de6\u4e0b\u89d2 \u7684\u5750\u6807\uff0c\u00a0(xi2, yi2)\u00a0\u662f\u8be5\u77e9\u5f62\u00a0\u53f3\u4e0a\u89d2 \u7684\u5750\u6807\u3002\n\n\u8ba1\u7b97\u5e73\u9762\u4e2d\u6240\u6709\u00a0rectangles\u00a0\u6240\u8986\u76d6\u7684 \u603b\u9762\u79ef \u3002\u4efb\u4f55\u88ab\u4e24\u4e2a\u6216\u591a\u4e2a\u77e9\u5f62\u8986\u76d6\u7684\u533a\u57df\u5e94\u53ea\u8ba1\u7b97 \u4e00\u6b21 \u3002\n\n\u8fd4\u56de \u603b\u9762\u79ef \u3002\u56e0\u4e3a\u7b54\u6848\u53ef\u80fd\u592a\u5927\uff0c\u8fd4\u56de\u00a0109\u00a0+ 7 \u7684\u00a0\u6a21\u00a0\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1arectangles = [[0,0,2,2],[1,0,2,3],[1,0,3,1]]\n\u8f93\u51fa\uff1a6\n\u89e3\u91ca\uff1a\u5982\u56fe\u6240\u793a\uff0c\u4e09\u4e2a\u77e9\u5f62\u8986\u76d6\u4e86\u603b\u9762\u79ef\u4e3a 6 \u7684\u533a\u57df\u3002\n\u4ece(1,1)\u5230(2,2)\uff0c\u7eff\u8272\u77e9\u5f62\u548c\u7ea2\u8272\u77e9\u5f62\u91cd\u53e0\u3002\n\u4ece(1,0)\u5230(2,3)\uff0c\u4e09\u4e2a\u77e9\u5f62\u90fd\u91cd\u53e0\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1arectangles = [[0,0,1000000000,1000000000]]\n\u8f93\u51fa\uff1a49\n\u89e3\u91ca\uff1a\u7b54\u6848\u662f 1018 \u5bf9 (109 + 7) \u53d6\u6a21\u7684\u7ed3\u679c\uff0c \u5373 49 \u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= rectangles.length <= 200\n\n\trectanges[i].length = 4\n\n\t0 <= xi1, yi1, xi2, yi2\u00a0<= 109\n\n\txi1\u00a0<= xi2\n\n\tyi1\u00a0<= yi2\n\n\t\u6240\u6709\u77e9\u9635\u9762\u79ef\u4e0d\u4e3a 0\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1arectangles\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def rectangleArea(self, rectangles: List[List[int]]) -> int:\n        hbound = set()\n        for rect in rectangles:\n            # \u4e0b\u8fb9\u754c\n            hbound.add(rect[1])\n            # \u4e0a\u8fb9\u754c\n            hbound.add(rect[3])\n        \n        hbound = sorted(hbound)\n        m = len(hbound)\n        # \u300c\u601d\u8def\u4e0e\u7b97\u6cd5\u90e8\u5206\u300d\u7684 length \u6570\u7ec4\u5e76\u4e0d\u9700\u8981\u663e\u5f0f\u5730\u5b58\u50a8\u4e0b\u6765\n        # length[i] \u53ef\u4ee5\u901a\u8fc7 hbound[i+1] - hbound[i] \u5f97\u5230\n        seg = [0] * (m - 1)\n\n        sweep = list()\n        for i, rect in enumerate(rectangles):\n            # \u5de6\u8fb9\u754c\n            sweep.append((rect[0], i, 1))\n            # \u53f3\u8fb9\u754c\n            sweep.append((rect[2], i, -1))\n        sweep.sort()\n\n        ans = i = 0\n        while i < len(sweep):\n            j = i\n            while j + 1 < len(sweep) and sweep[i][0] == sweep[j + 1][0]:\n                j += 1\n            if j + 1 == len(sweep):\n                break\n            \n            # \u4e00\u6b21\u6027\u5730\u5904\u7406\u6389\u4e00\u6279\u6a2a\u5750\u6807\u76f8\u540c\u7684\u5de6\u53f3\u8fb9\u754c\n            for k in range(i, j + 1):\n                _, idx, diff = sweep[k]\n                left, right = rectangles[idx][1], rectangles[idx][3]\n                for x in range(m - 1):\n                    if left <= hbound[x] and hbound[x + 1] <= right:\n                        seg[x] += diff\n            \n            cover = 0\n            for k in range(m - 1):\n                if seg[k] > 0:\n                    cover += (hbound[k + 1] - hbound[k])\n            ans += cover * (sweep[j + 1][0] - sweep[j][0])\n            i = j + 1\n        \n        return ans % (10**9 + 7)\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.rectangleArea(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "int",
    [["[[0,0,2,2],[1,0,2,3],[1,0,3,1]]", "6"], ["[[0,0,1000000000,1000000000]]", "49"]],
    ["segment-tree", "array", "ordered-set", "sweep-line", "\u6811"],
    )
