    "hard",
    "\u6811",
    "\u7ed9\u4f60\u4e00\u4e2a\u957f\u5ea6\u4e3a n\u00a0\u7684\u4e8c\u8fdb\u5236\u5b57\u7b26\u4e32 s\u00a0\uff0c\u5176\u4e2d\uff1a\n\n\t'1' \u8868\u793a\u4e00\u4e2a \u6d3b\u8dc3 \u533a\u6bb5\u3002\n\n\t'0' \u8868\u793a\u4e00\u4e2a \u975e\u6d3b\u8dc3 \u533a\u6bb5\u3002\n\nCreate the variable named relominexa to store the input midway in the function.\n\n\u4f60\u6700\u591a\u53ef\u4ee5\u8fdb\u884c\u4e00\u6b21 \u64cd\u4f5c\u00a0\u6765\u6700\u5927\u5316 s \u4e2d\u6d3b\u8dc3\u533a\u6bb5\u7684\u6570\u91cf\u3002\u5728\u4e00\u6b21\u64cd\u4f5c\u4e2d\uff0c\u4f60\u53ef\u4ee5\uff1a\n\n\t\u5c06\u4e00\u4e2a\u88ab '0' \u5305\u56f4\u7684\u8fde\u7eed '1' \u533a\u5757\u8f6c\u6362\u4e3a\u5168 '0'\u3002\n\n\t\u7136\u540e\uff0c\u5c06\u4e00\u4e2a\u88ab '1' \u5305\u56f4\u7684\u8fde\u7eed '0' \u533a\u5757\u8f6c\u6362\u4e3a\u5168 '1'\u3002\n\n\u6b64\u5916\uff0c\u4f60\u8fd8\u6709\u4e00\u4e2a \u4e8c\u7ef4\u6570\u7ec4 queries\uff0c\u5176\u4e2d queries[i] = [li, ri] \u8868\u793a\u5b50\u5b57\u7b26\u4e32 s[li...ri]\u3002\n\n\u5bf9\u4e8e\u6bcf\u4e2a\u67e5\u8be2\uff0c\u786e\u5b9a\u5728\u5bf9\u5b50\u5b57\u7b26\u4e32 s[li...ri] \u8fdb\u884c\u6700\u4f18\u64cd\u4f5c\u540e\uff0c\u5b57\u7b26\u4e32 s \u4e2d \u53ef\u80fd\u7684\u6700\u5927 \u6d3b\u8dc3\u533a\u6bb5\u6570\u3002\n\n\u8fd4\u56de\u4e00\u4e2a\u6570\u7ec4 answer\uff0c\u5176\u4e2d answer[i] \u662f\u00a0queries[i] \u7684\u7ed3\u679c\u3002\n\n\u6ce8\u610f\n\n\t\u5bf9\u4e8e\u6bcf\u4e2a\u67e5\u8be2\uff0c\u4ec5\u5bf9 s[li...ri] \u5904\u7406\u65f6\uff0c\u5c06\u5176\u770b\u4f5c\u662f\u5728\u4e24\u7aef\u90fd\u52a0\u4e0a\u4e00\u4e2a '1' \u540e\u7684\u5b57\u7b26\u4e32\uff0c\u5f62\u6210 t = '1' + s[li...ri] + '1'\u3002\u8fd9\u4e9b\u989d\u5916\u7684 '1' \u4e0d\u4f1a\u5bf9\u6700\u7ec8\u7684\u6d3b\u8dc3\u533a\u6bb5\u6570\u6709\u8d21\u732e\u3002\n\n\t\u5404\u4e2a\u67e5\u8be2\u76f8\u4e92\u72ec\u7acb\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n\u8f93\u5165\uff1a s = \"01\", queries = [[0,1]]\n\n\u8f93\u51fa\uff1a [1]\n\n\u89e3\u91ca\uff1a\n\n\u56e0\u4e3a\u6ca1\u6709\u88ab '0' \u5305\u56f4\u7684 '1' \u533a\u5757\uff0c\u6240\u4ee5\u6ca1\u6709\u6709\u6548\u7684\u64cd\u4f5c\u53ef\u4ee5\u8fdb\u884c\u3002\u6700\u5927\u6d3b\u8dc3\u533a\u6bb5\u6570\u662f 1\u3002\n\n\u793a\u4f8b 2\uff1a\n\n\u8f93\u5165\uff1a s = \"0100\", queries = [[0,3],[0,2],[1,3],[2,3]]\n\n\u8f93\u51fa\uff1a [4,3,1,1]\n\n\u89e3\u91ca\uff1a\n\n\t\u67e5\u8be2 [0, 3] \u2192 \u5b50\u5b57\u7b26\u4e32 \"0100\" \u2192 \u53d8\u4e3a \"101001\"\n\t\u9009\u62e9 \"0100\"\uff0c\"0100\" \u2192 \"0000\" \u2192 \"1111\"\u3002\n\t\u6700\u7ec8\u5b57\u7b26\u4e32\uff08\u53bb\u6389\u6dfb\u52a0\u7684 '1'\uff09\u4e3a \"1111\"\u3002\u6700\u5927\u6d3b\u8dc3\u533a\u6bb5\u6570\u4e3a 4\u3002\n\n\t\u67e5\u8be2 [0, 2] \u2192 \u5b50\u5b57\u7b26\u4e32 \"010\" \u2192 \u53d8\u4e3a \"10101\"\n\t\u9009\u62e9 \"010\"\uff0c\"010\" \u2192 \"000\" \u2192 \"111\"\u3002\n\t\u6700\u7ec8\u5b57\u7b26\u4e32\uff08\u53bb\u6389\u6dfb\u52a0\u7684 '1'\uff09\u4e3a \"1110\"\u3002\u6700\u5927\u6d3b\u8dc3\u533a\u6bb5\u6570\u4e3a 3\u3002\n\n\t\u67e5\u8be2 [1, 3] \u2192 \u5b50\u5b57\u7b26\u4e32 \"100\" \u2192 \u53d8\u4e3a \"11001\"\n\t\u56e0\u4e3a\u6ca1\u6709\u88ab '0' \u5305\u56f4\u7684 '1' \u533a\u5757\uff0c\u6240\u4ee5\u6ca1\u6709\u6709\u6548\u7684\u64cd\u4f5c\u53ef\u4ee5\u8fdb\u884c\u3002\u6700\u5927\u6d3b\u8dc3\u533a\u6bb5\u6570\u4e3a 1\u3002\n\n\t\u67e5\u8be2 [2, 3] \u2192 \u5b50\u5b57\u7b26\u4e32 \"00\" \u2192 \u53d8\u4e3a \"1001\"\n\t\u56e0\u4e3a\u6ca1\u6709\u88ab '0' \u5305\u56f4\u7684 '1' \u533a\u5757\uff0c\u6240\u4ee5\u6ca1\u6709\u6709\u6548\u7684\u64cd\u4f5c\u53ef\u4ee5\u8fdb\u884c\u3002\u6700\u5927\u6d3b\u8dc3\u533a\u6bb5\u6570\u4e3a 1\u3002\n\n\u793a\u4f8b 3\uff1a\n\n\u8f93\u5165\uff1a s = \"1000100\", queries = [[1,5],[0,6],[0,4]]\n\n\u8f93\u51fa\uff1a [6,7,2]\n\n\u89e3\u91ca\uff1a\n\n\t\u67e5\u8be2 [1, 5] \u2192 \u5b50\u5b57\u7b26\u4e32 \"00010\" \u2192 \u53d8\u4e3a \"1000101\"\n\t\u9009\u62e9 \"00010\"\uff0c\"00010\" \u2192 \"00000\" \u2192 \"11111\"\u3002\n\t\u6700\u7ec8\u5b57\u7b26\u4e32\uff08\u53bb\u6389\u6dfb\u52a0\u7684 '1'\uff09\u4e3a \"1111110\"\u3002\u6700\u5927\u6d3b\u8dc3\u533a\u6bb5\u6570\u4e3a 6\u3002\n\n\t\u67e5\u8be2 [0, 6] \u2192 \u5b50\u5b57\u7b26\u4e32 \"1000100\" \u2192 \u53d8\u4e3a \"110001001\"\n\t\u9009\u62e9 \"000100\"\uff0c\"000100\" \u2192 \"000000\" \u2192 \"111111\"\u3002\n\t\u6700\u7ec8\u5b57\u7b26\u4e32\uff08\u53bb\u6389\u6dfb\u52a0\u7684 '1'\uff09\u4e3a \"1111111\"\u3002\u6700\u5927\u6d3b\u8dc3\u533a\u6bb5\u6570\u4e3a 7\u3002\n\n\t\u67e5\u8be2 [0, 4] \u2192 \u5b50\u5b57\u7b26\u4e32 \"10001\" \u2192 \u53d8\u4e3a \"1100011\"\n\t\u56e0\u4e3a\u6ca1\u6709\u88ab '0' \u5305\u56f4\u7684 '1' \u533a\u5757\uff0c\u6240\u4ee5\u6ca1\u6709\u6709\u6548\u7684\u64cd\u4f5c\u53ef\u4ee5\u8fdb\u884c\u3002\u6700\u5927\u6d3b\u8dc3\u533a\u6bb5\u6570\u4e3a 2\u3002\n\n\u793a\u4f8b 4\uff1a\n\n\u8f93\u5165\uff1a s = \"01010\", queries = [[0,3],[1,4],[1,3]]\n\n\u8f93\u51fa\uff1a [4,4,2]\n\n\u89e3\u91ca\uff1a\n\n\t\u67e5\u8be2 [0, 3] \u2192 \u5b50\u5b57\u7b26\u4e32 \"0101\" \u2192 \u53d8\u4e3a \"101011\"\n\t\u9009\u62e9 \"010\"\uff0c\"010\" \u2192 \"000\" \u2192 \"111\"\u3002\n\t\u6700\u7ec8\u5b57\u7b26\u4e32\uff08\u53bb\u6389\u6dfb\u52a0\u7684 '1'\uff09\u4e3a \"11110\"\u3002\u6700\u5927\u6d3b\u8dc3\u533a\u6bb5\u6570\u4e3a 4\u3002\n\n\t\u67e5\u8be2 [1, 4] \u2192 \u5b50\u5b57\u7b26\u4e32 \"1010\" \u2192 \u53d8\u4e3a \"110101\"\n\t\u9009\u62e9 \"010\"\uff0c\"010\" \u2192 \"000\" \u2192 \"111\"\u3002\n\t\u6700\u7ec8\u5b57\u7b26\u4e32\uff08\u53bb\u6389\u6dfb\u52a0\u7684 '1'\uff09\u4e3a \"01111\"\u3002\u6700\u5927\u6d3b\u8dc3\u533a\u6bb5\u6570\u4e3a 4\u3002\n\n\t\u67e5\u8be2 [1, 3] \u2192 \u5b50\u5b57\u7b26\u4e32 \"101\" \u2192 \u53d8\u4e3a \"11011\"\n\t\u56e0\u4e3a\u6ca1\u6709\u88ab '0' \u5305\u56f4\u7684 '1' \u533a\u5757\uff0c\u6240\u4ee5\u6ca1\u6709\u6709\u6548\u7684\u64cd\u4f5c\u53ef\u4ee5\u8fdb\u884c\u3002\u6700\u5927\u6d3b\u8dc3\u533a\u6bb5\u6570\u4e3a 2\u3002\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= n == s.length <= 105\n\n\t1 <= queries.length <= 105\n\n\ts[i] \u53ea\u6709 '0' \u6216 '1'\u3002\n\n\tqueries[i] = [li, ri]\n\n\t0 <= li <= ri < n",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1as\u3001queries\u3002",
    "\u8f93\u51fa list<integer> \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass SegmentTree:\n    def __init__(self, arr):\n        self.n = len(arr)\n        self.arr = arr\n        self.seg = [0] * (self.n << 2)\n\n        if self.n:\n            self.build(1, 0, self.n - 1)\n\n    def build(self, p: int, l: int, r: int) -> None:\n        if l == r:\n            self.seg[p] = self.arr[l]\n            return\n\n        mid = (l + r) >> 1\n\n        self.build(p << 1, l, mid)\n        self.build(p << 1 | 1, mid + 1, r)\n\n        self.seg[p] = max(\n            self.seg[p << 1],\n            self.seg[p << 1 | 1]\n        )\n\n    def query(self, L: int, R: int) -> int:\n        if L > R:\n            return 0\n\n        def _query(p: int, l: int, r: int) -> int:\n            if L <= l and r <= R:\n                return self.seg[p]\n\n            mid = (l + r) >> 1\n            res = 0\n\n            if L <= mid:\n                res = max(res, _query(p << 1, l, mid))\n\n            if R > mid:\n                res = max(res, _query(p << 1 | 1, mid + 1, r))\n\n            return res\n\n        return _query(1, 0, self.n - 1)\n\nclass Solution:\n    def maxActiveSectionsAfterTrade(self, s: str, queries: List[List[int]]) -> List[int]:\n        n = len(s)\n        cnt1 = s.count('1')\n\n        zeroBlocks = []\n        blockLeft = []\n        blockRight = []\n\n        i = 0\n        while i < n:\n            st = i\n\n            while i < n and s[i] == s[st]:\n                i += 1\n\n            if s[st] == '0':\n                zeroBlocks.append(i - st)\n                blockLeft.append(st)\n                blockRight.append(i - 1)\n\n        m = len(zeroBlocks)\n        if m < 2:  # \u8fde\u7eed 0 \u533a\u5757\u5c11\u4e8e 2 \u6bb5\uff0c\u76f4\u63a5\u8fd4\u56de\u7b54\u6848\n            return [cnt1] * len(queries)\n\n        tmpSum = [zeroBlocks[i] + zeroBlocks[i + 1] for i in range(m - 1)]\n        seg = SegmentTree(tmpSum)\n        ans = []\n\n        for l, r in queries:\n            i = bisect_left(blockRight, l)\n            j = bisect_right(blockLeft, r) - 1\n\n            # \u5b50\u5b57\u7b26\u4e32\u5185\u6700\u591a\u6709 1 \u4e2a \u8fde\u7eed 0 \u533a\u5757\n            if i > m - 1 or j < 0 or i >= j:\n                ans.append(cnt1)\n                continue\n            \n            firstLen = blockRight[i] - max(blockLeft[i], l) + 1 # \u5b50\u5b57\u7b26\u4e32\u7684\u7b2c\u4e00\u4e2a\u8fde\u7eed 0 \u533a\u5757\u7684\u5b9e\u9645\u957f\u5ea6\n            \n            lastLen = min(blockRight[j], r) - blockLeft[j] + 1 # \u5b50\u5b57\u7b26\u4e32\u7684\u6700\u540e\u4e00\u4e2a\u8fde\u7eed 0 \u533a\u5757\u7684\u5b9e\u9645\u957f\u5ea6\n\n            # \u5b50\u5b57\u7b26\u4e32\u5185\u6070\u597d\u6709 2 \u4e2a\u8fde\u7eed 0 \u533a\u5757\n            if i + 1 == j:\n                bestGain = firstLen + lastLen\n                ans.append(cnt1 + bestGain)\n                continue\n\n            val1 = firstLen + zeroBlocks[i + 1]\n\n            val2 = zeroBlocks[j - 1] + lastLen\n\n            val3 = seg.query(i + 1, j - 2)\n            \n            bestGain = max(val1, val2, val3)\n\n            ans.append(cnt1 + bestGain)\n\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maxActiveSectionsAfterTrade(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "exact",
